#include <stdio.h>

struct point {
    int x;
    int y;
};

void translate(struct point *p, int dx, int dy) {
    p->x += dx;
    p->y += dy;
}

int main(void) {
    struct point pt;
    int k;
    scanf("%d %d %d", &pt.x, &pt.y, &k);
    for (int i = 0; i < k; i++) {
        int dx, dy;
        scanf("%d %d", &dx, &dy);
        translate(&pt, dx, dy);
    }
    printf("%d %d\n", pt.x, pt.y);
    return 0;
}

