#include <stdio.h>
#include <string.h>

struct participant {
    char name[21];
    int score;
};

int ranks_before(const struct participant *a, const struct participant *b) {
    if (a->score != b->score) {
        return a->score > b->score;
    }
    return strcmp(a->name, b->name) < 0;
}

int main(void) {
    struct participant list[100];
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%20s %d", list[i].name, &list[i].score);
    }
    for (int i = 0; i < n - 1; i++) {
        int best = i;
        for (int j = i + 1; j < n; j++) {
            if (ranks_before(&list[j], &list[best])) {
                best = j;
            }
        }
        struct participant tmp = list[i];
        list[i] = list[best];
        list[best] = tmp;
    }
    for (int i = 0; i < n; i++) {
        printf("%s %d\n", list[i].name, list[i].score);
    }
    return 0;
}

